import hashlib
import json
import pathlib
import subprocess
import sys

ROOT = pathlib.Path('/workspace/scratch/ac5966c4c370')
OUT = pathlib.Path('/tmp/cp11c-review-toolchain-setup')
OUT.mkdir(exist_ok=True)
BINS = {
    'baseline': (ROOT / 'binaries/combined-e8e274c1', '3ae400c2eaa83d5643362b5cd1aa29915844904fe95ee01d69900b2a2612b0ba'),
    'candidate': (ROOT / 'binaries/cp11c-4b2beb13', '65281f6c3f86c7be8ee82d76263eb52fb6ccdf0352ad88737a09b0702af4d414'),
}
CLANG = ROOT / 'toolchains/llvm-23.1.4/bin/clang'
CASES = [
    ('direct-unit', 'fn consume(u:()){} fn sum(x:i64,y:i64)->i64=>x+y fn result()->i64{consume(());return sum(20,22)}', 'result', '42\n', 0),
    ('function-pointer', 'fn inc(x:i32)->i32=>x+1;fn result()->i32{let f:fn(i32)->i32=inc;return f(41)}', 'result', '42\n', 0),
    ('copy-environment', 'fn calculate(base:i64)->i64{let f=move(delta)=>base+delta;return f(1)+f(2)}fn result()->i64{return calculate(40)+calculate(100)}', 'result', '286\n', 0),
    ('borrowed-mut-environment', 'fn result()->i32{var x=1;var f=()=>{x=2;return x;};let n=f();return n+x;}', 'result', '4\n', 0),
    ('unit-closure', 'fn unit(){}fn result()->i64{let blank=unit();let f=move(x)=>{blank;return x;};let run=()=>{};run();return f(42);}', 'result', '42\n', 0),
    ('owned-once-cleanup', '''extern "C" fn putchar(x:i32)->i32;
resource R{code:i32}impl Drop for R{fn drop(self:Self){unsafe{putchar(.code)}}}
package State<F>{manages ticket:R;callback:F}
fn pack<F:FnOnce()->i32>(callback:F)->State<F>{return State::<F>{ticket:R{code:84},callback:callback}}
fn make(n:i32)->impl FnOnce()->i32{let r=R{code:n};return move()=>{let value=give r;return value.code}}
fn main()->i32{let state=pack(make(65));let once=state.callback;return once()-65}
''', None, 'AT', 0),
    ('reject-arity', 'fn add(x:i64,y:i64)->i64=>x+y;fn result()->i64=>add(42)', 'result', None, None),
    ('reject-live-borrow-write', 'fn result()->i32{var x=1;let f=()=>x;x=2;return f();}', 'result', None, None),
]

def sha(data):
    return hashlib.sha256(data).hexdigest()

for path, expected in BINS.values():
    assert sha(path.read_bytes()) == expected

records = []
failures = []
for name, text, entry, expected_stdout, expected_exit in CASES:
    work = OUT / name
    work.mkdir(exist_ok=True)
    source = work / 'main.zil'
    source.write_text(text)
    rows = {}
    for arm, (binary, _) in BINS.items():
        output = work / arm
        ll = output.with_suffix('.ll')
        sentinel = b'previous executable must survive rejection\n'
        ll_sentinel = b'previous machine sidecar must survive rejection\n'
        if expected_stdout is None:
            output.write_bytes(sentinel)
            ll.write_bytes(ll_sentinel)
        argv = [str(binary), 'build', str(source), '-o', str(output), '--json', '--backend', 'llvm-api', '--clang', str(CLANG), '--opt', 'O0', '--codegen-units', '1', '--codegen-jobs', '1']
        if entry is not None:
            argv.extend(['--entry', entry])
        run = subprocess.run(argv, capture_output=True, timeout=60)
        (work / f'{arm}.compile.stdout').write_bytes(run.stdout)
        (work / f'{arm}.compile.stderr').write_bytes(run.stderr)
        report = json.loads(run.stdout)
        row = {'argv': argv, 'compiler_exit': run.returncode, 'compiler_stdout_sha256': sha(run.stdout), 'compiler_stderr_sha256': sha(run.stderr), 'report': report}
        rows[arm] = row
        if expected_stdout is not None:
            if run.returncode or report.get('status') != 'Success' or report.get('verification_runs') != 1:
                failures.append({'case': name, 'arm': arm, 'reason': 'expected successful complete compilation with exactly one Verify', 'report': report})
                continue
            model = pathlib.Path(report['artifacts']['llvm']).read_bytes()
            row['machine_ir_sha256'] = sha(model)
            row['machine_ir_bytes'] = len(model)
            row['executable_sha256'] = sha(output.read_bytes())
            native = subprocess.run([str(output)], capture_output=True, timeout=5)
            row['native'] = {'exit': native.returncode, 'stdout': native.stdout.decode(), 'stderr': native.stderr.decode()}
            if row['native'] != {'exit': expected_exit, 'stdout': expected_stdout, 'stderr': ''}:
                failures.append({'case': name, 'arm': arm, 'reason': 'native result mismatch', 'observed': row['native']})
        else:
            row['previous_executable_preserved'] = output.read_bytes() == sentinel
            row['previous_machine_sidecar_preserved'] = ll.read_bytes() == ll_sentinel
            if report.get('status') == 'Success' or not run.returncode or not row['previous_executable_preserved'] or not row['previous_machine_sidecar_preserved']:
                failures.append({'case': name, 'arm': arm, 'reason': 'rejection/publication contract mismatch', 'observed': row})
    old, new = rows['baseline'], rows['candidate']
    for field in ['status', 'phase', 'diagnostics', 'verification_runs']:
        if old['report'].get(field) != new['report'].get(field):
            failures.append({'case': name, 'field': field, 'reason': 'report mismatch'})
    if expected_stdout is not None and 'machine_ir_sha256' in old and 'machine_ir_sha256' in new:
        old_ir = pathlib.Path(old['report']['artifacts']['llvm']).read_bytes()
        new_ir = pathlib.Path(new['report']['artifacts']['llvm']).read_bytes()
        if old_ir != new_ir:
            failures.append({'case': name, 'reason': 'machine text differs'})
    records.append({'case': name, 'source': text, 'source_path': str(source), 'source_sha256': sha(source.read_bytes()), 'expected_stdout': expected_stdout, 'expected_exit': expected_exit, 'arms': rows})
    (OUT / 'results.json').write_text(json.dumps({'records': records, 'failures': failures}, indent=2) + '\n')
    print(json.dumps({'case': name, 'baseline_status': old['report'].get('status'), 'candidate_status': new['report'].get('status'), 'failures_so_far': len(failures)}), flush=True)

print(json.dumps({'source_cases': len(CASES), 'positive_cases': sum(case[3] is not None for case in CASES), 'negative_cases': sum(case[3] is None for case in CASES), 'failures': failures}), flush=True)
sys.exit(bool(failures))

